package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type LineIterator struct {
	lines []string
	idx   int
}

func NewLineIterator() *LineIterator {
	scanner := bufio.NewScanner(os.Stdin)
	var lines []string
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line != "" {
			lines = append(lines, line)
		}
	}
	return &LineIterator{lines: lines}
}

func (it *LineIterator) next() string {
	if it.idx >= len(it.lines) {
		return ""
	}
	line := it.lines[it.idx]
	it.idx++
	return line
}

func (it *LineIterator) Num() int {
	line := it.next()
	val, _ := strconv.Atoi(line)
	return val
}

func (it *LineIterator) Nums() []int {
	line := it.next()
	parts := strings.Fields(line)
	res := make([]int, len(parts))
	for i, p := range parts {
		res[i], _ = strconv.Atoi(p)
	}
	return res
}

func (it *LineIterator) Line() string {
	return it.next()
}

func main() {
	nl := NewLineIterator()
	nk := nl.Nums()
	if len(nk) < 2 {
		return
	}
	n, k := nk[0], nk[1]
	a := nl.Nums()
	r := make([]int, n)
	for _, i := range a {
		for j := i - 1; j < n && r[j] == 0; j++ {
			r[j] = i
		}
	}
	for idx, val := range r {
		if idx > 0 {
			fmt.Print(" ")
		}
		fmt.Print(val)
	}
	fmt.Println()
}

