	"strings"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	scanInt := func() int {
		scanner.Scan()
		val, _ := strconv.Atoi(scanner.Text())
		return val
	}

	n := scanInt()
	k := scanInt()

	a := make([]int, k)
	for i := 0; i < k; i++ {
		a[i] = scanInt()
	}

	r := make([]int, n)

	for _, val := range a {
		start := val - 1
		for j := start; j < n && r[j] == 0; j++ {
			r[j] = val
		}
	}

	var sb strings.Builder
	for i, val := range r {
		if i > 0 {
			sb.WriteString(" ")
		}
		sb.WriteString(strconv.Itoa(val))
	}
	fmt.Println(sb.String())
}

